import assert from "node:assert/strict";
import { test } from "node:test";
import {
  extractVideos,
  isTikTokApiUrl,
  isTikTokCaptionUrl,
  pickCaptionTrack,
  videoIdFrom,
  type CaptionTrack,
} from "../src/tiktok.ts";

// Mirrors the embedded data on a real music-only TikTok page seen on
// 2026-10-12, trimmed to the fields the extension reads (author anonymized).
const embeddedPage = {
  __DEFAULT_SCOPE__: {
    "webapp.app-context": {},
    "webapp.video-detail": {
      statusCode: 0,
      itemInfo: {
        itemStruct: {
          id: "7621991999251467550",
          desc: "she ws so sweet #ubereats #fyp",
          author: { uniqueId: "example_creator" },
          textExtra: [{ hashtagName: "ubereats" }, { hashtagName: "fyp" }],
          stickersOnItem: [
            { stickerText: ["sneaking taco bell into school"], stickerType: 4 },
          ],
          IsAigc: false,
          AIGCDescription: "",
          ShowAIGC: true,
          video: {
            subtitleInfos: [],
            claInfo: {
              captionInfos: [],
              enableAutoCaption: true,
              hasOriginalAudio: false,
              noCaptionReason: 3,
            },
          },
        },
      },
    },
  },
};

// A feed response shaped like TikTok's /api/recommend/item_list/. The caption
// entries use TikTok's field names from before 2026 (see toCaptionTrack).
const feedResponse = {
  hasMore: true,
  itemList: [
    {
      id: "7600000000000000001",
      desc: "Magnesium cures insomnia",
      author: { uniqueId: "wellnesscoach" },
      IsAigc: false,
      AIGCDescription: "",
      video: {
        claInfo: {
          captionInfos: [
            {
              language: "eng-US",
              url: "https://v16-webapp.tiktok.com/captions/en.vtt",
              captionFormat: "webvtt",
              isAutoGen: true,
              isOriginalCaption: true,
            },
          ],
        },
        subtitleInfos: [
          {
            LanguageCodeName: "eng-US",
            Url: "https://v16-webapp.tiktok.com/captions/en.vtt",
            Format: "webvtt",
            Source: "ASR",
          },
          {
            LanguageCodeName: "spa-ES",
            Url: "https://v16-webapp.tiktok.com/captions/es.vtt",
            Format: "webvtt",
            Source: "MT",
          },
        ],
      },
    },
    {
      id: "7600000000000000002",
      desc: "Flooding downtown right now #veo3",
      author: { uniqueId: "breakingclips" },
      IsAigc: true,
      AIGCDescription: "Creator labeled as AI-generated",
      video: {},
    },
    { id: "not-a-video" },
  ],
};

const track = (overrides: Partial<CaptionTrack>): CaptionTrack => ({
  url: "https://v16-webapp.tiktok.com/captions/x.vtt",
  language: "",
  format: "webvtt",
  autoGenerated: true,
  original: false,
  ...overrides,
});

