    <Cursor from={AI.cursorFrom} clickAt={AI.click} start={{ x: 1650, y: 1010 }} />
    <Popover
      openAt={AI.click + 3}
      sections={[
        {
          title: "Made with AI?",
          rows: [
            { text: "Likely AI", detail: "Likely · 2 of 3 signals", tone: "warn", resolveAt: AI.verdictAt },
            ...AI.signals,
          ],
        },
        {
          title: "Claims",
          rows: [
            {
              text: "Downtown Chicago is flooding right now",
              detail: "Contradicted · 2 sources",
              tone: "contradicted",
              resolveAt: AI.claimAt,
            },
          ],
        },
      ]}
    />
  </AbsoluteFill>
);

