const cp = require("child_process");
const original = cp.spawn;
cp.spawn = function (command, args, options) {
  const child = original.apply(this, arguments);
  const name = String(command).split(/[\\/]/).pop();
  console.error(`[spawn] ${name} pid=${child.pid} args=${JSON.stringify(args).slice(0, 120)}`);
  child.on("error", (e) => console.error(`[spawn-error] ${name}: ${e.code} ${e.message}`));
  child.on("exit", (code, signal) => console.error(`[exit] ${name} code=${code} signal=${signal}`));
  return child;
};
EOF
